// F1: only a signed-in washer may read a round. The app sends  Authorization: Bearer <Firebase ID token>.
// We verify the RS256 signature against Google's published securetoken certificates, check the
// claims, and require the token's phone number to belong to the washer being asked for.
// Needs n8n env NODE_FUNCTION_ALLOW_BUILTIN=crypto (Code nodes must be allowed to require('crypto')),
// FIREBASE_PROJECT_ID, and optionally WASHER_PHONES (see README). Any failure answers 401.
const crypto = require('crypto');
const PROJECT = String($env.FIREBASE_PROJECT_ID || '').trim();
if (!PROJECT) throw new Error('FIREBASE_PROJECT_ID env var is not set');
const CERT_URL = 'https://www.googleapis.com/robot/v1/metadata/x509/securetoken@system.gserviceaccount.com';

// phone (E.164) -> washer id: the same two washers as WASHERS / PHONE_TO_WASHER in the washer apps.
// Override with env WASHER_PHONES = {"+91XXXXXXXXXX":"chotte","+91YYYYYYYYYY":"shahrukh"}
let WASHER_BY_PHONE = { '+919000000001': 'chotte', '+919000000002': 'shahrukh' };
if ($env.WASHER_PHONES) {
  try { WASHER_BY_PHONE = JSON.parse($env.WASHER_PHONES) } catch (e) { throw new Error('WASHER_PHONES env var is not valid JSON') }
}

const deny = why => [{ json: { ok: false, status: 401, error: 'unauthorized', why } }];
const b64u = s => Buffer.from(String(s).replace(/-/g, '+').replace(/_/g, '/'), 'base64');

const asked = String((($('Round maango (webhook)').first().json.query) || {}).washer || '').toLowerCase();
const authz = String((($('Round maango (webhook)').first().json.headers) || {}).authorization || '');
const m = /^Bearer ([A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+)$/.exec(authz.trim());
if (!m) return deny('no bearer token');
if (m[1].length > 6000) return deny('token too long');
const [h64, p64, s64] = m[1].split('.');

let header, claims;
try { header = JSON.parse(b64u(h64).toString('utf8')); claims = JSON.parse(b64u(p64).toString('utf8')) }
catch (e) { return deny('unreadable token') }
if (!header || header.alg !== 'RS256' || typeof header.kid !== 'string') return deny('bad header');

// Google's signing certs, cached in workflow static data for max-age (default 1 h, at most 24 h).
// A kid we do not know triggers one refetch, at most every 5 minutes.
const sd = $getWorkflowStaticData('global');
const nowMs = Date.now();
async function fetchCerts() {
  const resp = await this.helpers.httpRequest({ method: 'GET', url: CERT_URL, json: true, returnFullResponse: true, timeout: 8000 });
  const certs = resp.body;
  if (!certs || typeof certs !== 'object' || !Object.keys(certs).length) throw new Error('no certs');
  const mm = /max-age=(\d+)/.exec(String((resp.headers || {})['cache-control'] || ''));
  const ttl = Math.min(Math.max(Number(mm && mm[1]) || 3600, 300), 86400) * 1000;
  sd.fbCerts = { certs, fetchedAt: nowMs, expiresAt: nowMs + ttl };
}
const cached = sd.fbCerts && sd.fbCerts.certs && sd.fbCerts.expiresAt > nowMs;
try {
  if (!cached) await fetchCerts.call(this);
  else if (!sd.fbCerts.certs[header.kid] && nowMs - sd.fbCerts.fetchedAt > 300000) await fetchCerts.call(this);
} catch (e) {
  if (!(sd.fbCerts && sd.fbCerts.certs)) return deny('certs unavailable');   // fail closed; stale certs are still fine
}
const pem = sd.fbCerts && sd.fbCerts.certs && sd.fbCerts.certs[header.kid];
if (!pem) return deny('unknown kid');

let sigOk = false;
try { sigOk = crypto.createVerify('RSA-SHA256').update(h64 + '.' + p64).verify(pem, b64u(s64)) } catch (e) { sigOk = false }
if (!sigOk) return deny('bad signature');

const nowS = Math.floor(nowMs / 1000), SKEW = 300;
if (claims.aud !== PROJECT) return deny('wrong aud');
if (claims.iss !== 'https://securetoken.google.com/' + PROJECT) return deny('wrong iss');
if (typeof claims.exp !== 'number' || claims.exp <= nowS) return deny('expired');
if (typeof claims.iat !== 'number' || claims.iat > nowS + SKEW) return deny('iat in future');
if (typeof claims.auth_time !== 'number' || claims.auth_time > nowS + SKEW) return deny('auth_time in future');
if (typeof claims.sub !== 'string' || !claims.sub || claims.sub.length > 128) return deny('bad sub');

const washer = Object.prototype.hasOwnProperty.call(WASHER_BY_PHONE, claims.phone_number) ? WASHER_BY_PHONE[claims.phone_number] : null;
if (!washer) return deny('phone is not a washer');
if (washer !== asked) return deny('token belongs to another washer');
return [{ json: { ok: true, washer } }];

// Rounds. Needs n8n env NOTION_TOKEN (an integration with access to Monthly Customers) and NOTION_CARS_DB.
// Rounds: every car of one area collected into one list (Notion "Monthly Customers", select property "Round").
// Pure functions, shared by the n8n Code node and the tests.
const ROUND_WASHERS = { chotte: 'chotte', shahrukh: 'shahrukh' };
const rtxt = p => ((p && (p.rich_text || p.title)) || []).map(t => t.plain_text).join('').trim();
const rpick = p => (p && p.select && p.select.name) || '';
const rslug = s => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 40);

/** Active, registered cars that are on a round. */
function roundCars(pages) {
  return (pages || []).filter(pg => {
    const p = pg.properties || {};
    if (rpick(p['Account Status']) !== 'Active') return false;
    if (!rpick(p['Round'])) return false;
    const reg = rtxt(p['Car Number']).toUpperCase().replace(/[^A-Z0-9]/g, '');
    return !!reg && !/NUMBERNEEDED/.test(reg);
  });
}

/** [{ id, name, areas, count, washer }] sorted by name. washer = the one who has most of its cars today ('' if none). */
function roundsOf(pages) {
  const by = {};
  roundCars(pages).forEach(pg => {
    const p = pg.properties, name = rpick(p['Round']), id = rslug(name);
    const r = by[id] = by[id] || { id, name, areas: new Set(), count: 0, w: {} };
    const area = rtxt(p['Area']); if (area) r.areas.add(area);
    r.count++;
    const w = ROUND_WASHERS[rpick(p['Washer']).toLowerCase()] || ''; r.w[w] = (r.w[w] || 0) + 1;
  });
  return Object.values(by).map(r => {
    const top = Object.entries(r.w).sort((a, b) => b[1] - a[1])[0];
    return { id: r.id, name: r.name, areas: [...r.areas].sort().join(' · '), count: r.count, washer: top ? top[0] : '' };
  }).sort((a, b) => a.name.localeCompare(b.name));
}

/** The Notion page ids that must change so every car of `roundId` belongs to `washer`. */
function pagesToMove(pages, roundId, washer) {
  if (!ROUND_WASHERS[washer]) return [];
  return roundCars(pages).filter(pg => rslug(rpick(pg.properties['Round'])) === roundId && (ROUND_WASHERS[rpick(pg.properties['Washer']).toLowerCase()] || '') !== washer).map(pg => pg.id);
}
const WASHER_LABEL = { chotte: 'Chotte', shahrukh: 'Shahrukh' };   // the Notion select option names

async function queryAll(http, headers, dbId) {
  const out = []; let cursor;
  for (let i = 0; i < 6; i++) {
    const r = await http({ method: 'POST', url: `https://api.notion.com/v1/databases/${dbId}/query`, headers,
      body: { filter: { property: 'Account Status', select: { equals: 'Active' } }, page_size: 100, ...(cursor ? { start_cursor: cursor } : {}) } });
    if (r.status !== 200 || !r.body) throw new Error('notion query ' + r.status);
    out.push(...(r.body.results || [])); if (!r.body.has_more) break; cursor = r.body.next_cursor;
  }
  return out;
}

/** body.action 'list' (default): the rounds. 'pick' + body.round: take a round, all its cars go to this washer. */
async function handleRounds({ washer, body, http, token, dbId }) {
  if (!ROUND_WASHERS[washer]) return { ok: false, error: 'unknown washer' };
  const headers = { Authorization: 'Bearer ' + token, 'Notion-Version': '2022-06-28', 'Content-Type': 'application/json' };
  const pages = await queryAll(http, headers, dbId);
  if (!(body && body.action === 'pick')) return { ok: true, rounds: roundsOf(pages), mine: (roundsOf(pages).find(r => r.washer === washer) || {}).id || '' };
  const round = rslug(body && body.round);
  const known = roundsOf(pages).find(r => r.id === round);
  if (!round || !known) return { ok: false, error: 'unknown round' };
  const ids = pagesToMove(pages, round, washer);
  let moved = 0;
  for (const id of ids) {
    const r = await http({ method: 'PATCH', url: 'https://api.notion.com/v1/pages/' + id, headers, body: { properties: { Washer: { select: { name: WASHER_LABEL[washer] } } } } });
    if (r.status === 200) moved++;
  }
  return { ok: moved === ids.length, moved, total: known.count, round };
}
if (typeof module !== 'undefined') module.exports = { roundsOf, pagesToMove, rslug, roundCars, handleRounds };

const helpers = this.helpers;
const http = async o => {
  try {
    const r = await helpers.httpRequest({ method: o.method, url: o.url, headers: o.headers, body: o.body, json: true, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 15000 });
    return { status: Number(r && r.statusCode) || 0, body: r && r.body };
  } catch (e) { return { status: 0, body: null } }
};
const hook = $('Round maango (webhook)').first().json;
const washer = String((hook.query || {}).washer || '').toLowerCase();
try {
  return [{ json: await handleRounds({ washer, body: hook.body || {}, http, token: $env.NOTION_TOKEN, dbId: $env.NOTION_CARS_DB || 'ca0440e9f6ab4e15bf35b9d720e2952b' }) }];
} catch (e) { return [{ json: { ok: false, error: 'rounds unavailable' } }]; }
